  register('mines', stage=>{const N=10,M=12;let cells=Array(N*N).fill(0),open=Array(N*N).fill(false),flag=Array(N*N).fill(false),over=false;for(let k=0;k<M;){const i=Math.floor(rand()*cells.length);if(cells[i]!==-1){cells[i]=-1;k++}}const neigh=i=>{const r=Math.floor(i/N),c=i%N,a=[];for(let dr=-1;dr<=1;dr++)for(let dc=-1;dc<=1;dc++){if(!dr&&!dc)continue;const rr=r+dr,cc=c+dc;if(rr>=0&&rr<N&&cc>=0&&cc<N)a.push(rr*N+cc)}return a};cells=cells.map((v,i)=>v===-1?-1:neigh(i).filter(j=>cells[j]===-1).length);stage.innerHTML=`<div class="message" id="msg">💣 ${M} mìn • chuột phải để cắm cờ</div><div id="board" class="mine-board" style="grid-template-columns:repeat(${N},34px)"></div>`;const bd=$('#board');function reveal(i){if(open[i]||flag[i])return;open[i]=true;if(cells[i]===0)neigh(i).forEach(reveal)}function draw(){bd.innerHTML=cells.map((v,i)=>`<button class="mine-cell ${open[i]?'open':''} ${flag[i]?'flag':''}" data-i="${i}">${flag[i]?'🚩':open[i]?(v===-1?'💣':v||''):''}</button>`).join('');$$('.mine-cell',bd).forEach(x=>{x.onclick=()=>{if(over)return;const i=+x.dataset.i;if(flag[i])return;if(cells[i]===-1){open=cells.map(()=>true);over=true;$('#msg').textContent='💥 Nổ mìn!'}else{reveal(i);if(open.filter(Boolean).length===cells.length-M){over=true;$('#msg').textContent='🎉 Dọn sạch bãi mìn!';award('mines',250,'Phá đảo Minesweeper')}}draw()};x.oncontextmenu=e=>{e.preventDefault();if(over||open[x.dataset.i])return;flag[x.dataset.i]=!flag[x.dataset.i];draw()}})}draw();});

  register('sudoku', stage=>{const puzzle='530070000600195000098000060800060003400803001700020006060000280000419005000080079', sol='534678912672195348198342567859761423426853791713924856961537284287419635345286179';stage.innerHTML=`<div class="message" id="msg">Điền đủ bảng rồi kiểm tra</div><div id="sdk" class="sudoku"></div><div class="row" style="margin-top:18px"><button class="primary-btn" id="check">Kiểm tra</button><button class="secondary-btn" id="hint">Gợi ý 1 ô</button></div>`;const box=$('#sdk');box.innerHTML=[...puzzle].map((v,i)=>`<input maxlength="1" inputmode="numeric" data-i="${i}" class="${v!=='0'?'given':''}" value="${v==='0'?'':v}" ${v!=='0'?'readonly':''}>`).join('');$$('input',box).forEach(x=>x.oninput=()=>x.value=x.value.replace(/[^1-9]/g,'').slice(0,1));$('#check').onclick=()=>{const val=$$('input',box).map(x=>x.value).join('');if(val===sol){$('#msg').textContent='✅ Chính xác!';award('sudoku',300,'Hoàn thành Sudoku')}else $('#msg').textContent=val.includes('')?'Chưa điền đủ.':'❌ Có ô chưa đúng.'};$('#hint').onclick=()=>{const empt=$$('input',box).filter(x=>!x.value&&!x.readOnly);if(!empt.length)return;const x=empt[Math.floor(rand()*empt.length)];x.value=sol[+x.dataset.i];x.style.color='#22c55e'};});

  register('2048', stage=>{let b=Array(16).fill(0),score=0,over=false;const add=()=>{const e=b.map((v,i)=>v?null:i).filter(x=>x!==null);if(e.length)b[e[Math.floor(rand()*e.length)]]=rand()<.9?2:4};add();add();stage.innerHTML=`<div class="message">Điểm: <b id="score">0</b> • dùng WASD / phím mũi tên</div><div id="g" class="g2048"></div>`;const g=$('#g');function merge(line){let a=line.filter(Boolean);for(let i=0;i<a.length-1;i++)if(a[i]===a[i+1]){a[i]*=2;score+=a[i];a.splice(i+1,1)}while(a.length<4)a.push(0);return a}function move(dir){if(over)return;const old=b.join(',');let nb=Array(16).fill(0);for(let k=0;k<4;k++){let line=[];for(let j=0;j<4;j++){let r,c;if(dir==='L'){r=k;c=j}else if(dir==='R'){r=k;c=3-j}else if(dir==='U'){r=j;c=k}else{r=3-j;c=k}line.push(b[r*4+c])}line=merge(line);for(let j=0;j<4;j++){let r,c;if(dir==='L'){r=k;c=j}else if(dir==='R'){r=k;c=3-j}else if(dir==='U'){r=j;c=k}else{r=3-j;c=k}nb[r*4+c]=line[j]}}b=nb;if(b.join(',')!==old){add();draw()}if(!b.includes(0)&&!['L','R','U','D'].some(d=>can(d))){over=true;award('2048',score,'Kết thúc 2048')}}function can(d){const copy=b.slice(),s=score;let changed=false;for(let k=0;k<4;k++){let line=[];for(let j=0;j<4;j++){let r,c;if(d==='L'){r=k;c=j}else if(d==='R'){r=k;c=3-j}else if(d==='U'){r=j;c=k}else{r=3-j;c=k}line.push(copy[r*4+c])}const m=merge(line);if(m.join()!=line.join())changed=true}score=s;return changed}function draw(){g.innerHTML=b.map(v=>`<div class="tile2048">${v||''}</div>`).join('');$('#score').textContent=score}function key(e){const m={ArrowLeft:'L',a:'L',A:'L',ArrowRight:'R',d:'R',D:'R',ArrowUp:'U',w:'U',W:'U',ArrowDown:'D',s:'D',S:'D'};if(m[e.key]){e.preventDefault();move(m[e.key])}}window.addEventListener('keydown',key);cleanup=()=>window.removeEventListener('keydown',key);draw();});

  register('memory', stage=>{
    const vals=[
      {icon:'🍕',label:'Pizza'},{icon:'☕',label:'Coffee'},{icon:'💻',label:'Laptop'},{icon:'🚀',label:'Rocket'},
      {icon:'🐼',label:'Panda'},{icon:'🎮',label:'Gaming'},{icon:'🍩',label:'Donut'},{icon:'⚽',label:'Football'}
    ], deck=shuffle([...vals,...vals].map((c,i)=>({...c,uid:i})));
    let open=[],matched=new Set(),moves=0,lock=false;
    stage.innerHTML=`<div class="card-stage memory-upgrade"><div class="table-head"><div><div class="eyebrow">CARD MEMORY</div><h2 class="card-title">Memory Match Deluxe</h2><p class="muted">Lật đúng từng cặp thẻ để hoàn tất bàn bài.</p></div><div class="row stats-inline"><div class="stat-chip"><span>Lượt lật</span><b id="m">0</b></div><div class="stat-chip"><span>Đã khớp</span><b id="pairCount">0/8</b></div></div></div><div id="mem" class="memory deluxe"></div><div id="memoryMsg" class="message">Tìm đủ 8 cặp bài để hoàn thành.</div></div>`;
    const mem=$('#mem'),msg=$('#memoryMsg');
    function draw(){
      const pairs=matched.size/2; $('#pairCount').textContent=`${pairs}/8`;
      mem.innerHTML=deck.map((card,i)=>{
        const flipped=matched.has(i)||open.includes(i),matchedClass=matched.has(i)?' is-matched':'';
        return `<button class="memory-card deluxe${flipped?' is-flipped':''}${matchedClass}" data-i="${i}" aria-label="Memory card ${i+1}"><span class="memory-card-inner"><span class="memory-face memory-back"><span class="memory-back-mark">QGT</span><small>Memory</small></span><span class="memory-face memory-front"><span class="memory-icon">${card.icon}</span><b>${escapeHtml(card.label)}</b></span></span></button>`;
      }).join('');
      $('.memory-card',mem).forEach(x=>x.onclick=()=>{
        const i=+x.dataset.i; if(lock||matched.has(i)||open.includes(i)) return;
        open.push(i); beep(620,.02); draw();
        if(open.length===2){
          moves++; $('#m').textContent=moves; lock=true;
          const a=deck[open[0]],b=deck[open[1]];
          if(a.label===b.label){
            msg.textContent='✅ Chuẩn bài!';
            setTimeout(()=>{matched.add(open[0]); matched.add(open[1]); beep(780,.05); open=[]; lock=false; draw(); if(matched.size===deck.length){msg.textContent='🏆 Hoàn hảo! Bạn đã làm sạch toàn bộ bộ bài.'; award('memory',Math.max(50,320-moves*8),`Memory deluxe ${moves} lượt`)}},460);
          } else {
            msg.textContent='❌ Không khớp, thử lại nhé.';
            setTimeout(()=>{open=[]; lock=false; draw(); msg.textContent='Tìm đủ 8 cặp bài để hoàn thành.';},760);
          }
        }
      });
    }
    draw();
  });


  register('lights', stage=>{let b=Array(25).fill(false),moves=0;for(let i=0;i<12;i++)toggle(Math.floor(rand()*25),false);stage.innerHTML=`<div class="message">Lượt: <b id="m">0</b></div><div id="lights" class="lights"></div>`;const box=$('#lights');function toggle(i,count=true){const r=Math.floor(i/5),c=i%5;for(const[dr,dc]of[[0,0],[1,0],[-1,0],[0,1],[0,-1]]){const rr=r+dr,cc=c+dc;if(rr>=0&&rr<5&&cc>=0&&cc<5)b[rr*5+cc]=!b[rr*5+cc]}if(count)moves++}function draw(){box.innerHTML=b.map((v,i)=>`<button class="light ${v?'on':''}" data-i="${i}"></button>`).join('');$('#m').textContent=moves;$$('.light',box).forEach(x=>x.onclick=()=>{toggle(+x.dataset.i);if(b.every(v=>!v))award('lights',Math.max(50,250-moves*5),`Tắt đèn trong ${moves} lượt`);draw()})}draw();});

  register('hanoi', stage=>{let pegs=[[5,4,3,2,1],[],[]],sel=-1,moves=0;stage.innerHTML=`<div class="message">Chuyển tháp sang cọc phải • lượt: <b id="m">0</b></div><div id="hanoi" class="hanoi"></div>`;const box=$('#hanoi');function draw(){box.innerHTML=pegs.map((p,pi)=>`<div class="peg ${sel===pi?'selected':''}" data-p="${pi}">${p.map(d=>`<div class="disk" style="width:${40+d*18}px">${d}</div>`).join('')}</div>`).join('');$$('.peg',box).forEach(x=>x.onclick=()=>{const p=+x.dataset.p;if(sel<0){if(pegs[p].length)sel=p}else if(sel===p)sel=-1;else{const d=pegs[sel][pegs[sel].length-1],top=pegs[p][pegs[p].length-1];if(!top||d<top){pegs[p].push(pegs[sel].pop());moves++;$('#m').textContent=moves;if(pegs[2].length===5)award('hanoi',Math.max(100,500-moves*8),`Hoàn thành ${moves} lượt`)}sel=-1}draw()})}draw();});

  register('slide', stage=>{let b=[...Array(15)].map((_,i)=>i+1).concat(0);function shuffle(){for(let k=0;k<220;k++){const z=b.indexOf(0),r=Math.floor(z/4),c=z%4,opts=[];for(const[dr,dc]of[[1,0],[-1,0],[0,1],[0,-1]]){const rr=r+dr,cc=c+dc;if(rr>=0&&rr<4&&cc>=0&&cc<4)opts.push(rr*4+cc)}const j=opts[Math.floor(rand()*opts.length)];[b[z],b[j]]=[b[j],b[z]]}}shuffle();let moves=0;stage.innerHTML=`<div class="message">Lượt: <b id="m">0</b></div><div id="slide" class="slide-board"></div>`;const box=$('#slide');function draw(){box.innerHTML=b.map((v,i)=>`<button class="slide-tile ${v?'':'blank'}" data-i="${i}">${v||''}</button>`).join('');$$('.slide-tile',box).forEach(x=>x.onclick=()=>{const i=+x.dataset.i,z=b.indexOf(0),r=Math.floor(i/4),c=i%4,zr=Math.floor(z/4),zc=z%4;if(Math.abs(r-zr)+Math.abs(c-zc)!==1)return;[b[i],b[z]]=[b[z],b[i]];moves++;$('#m').textContent=moves;if(b.every((v,i)=>i===15?v===0:v===i+1))award('slide',Math.max(50,600-moves*3),`Xếp xong ${moves} lượt`);draw()})}draw();});

  register('reaction', stage=>{let t=null,start=0,stateR='idle',best=Infinity;stage.innerHTML=`<div id="rx" class="reaction-box"><div>Nhấn để bắt đầu<br><span class="muted">Khi ô chuyển xanh, nhấn càng nhanh càng tốt.</span></div></div><div class="message" id="msg"></div>`;const rx=$('#rx');rx.onclick=()=>{if(stateR==='idle'||stateR==='done'){stateR='wait';rx.classList.remove('ready');rx.innerHTML='Chờ màu xanh...';$('#msg').textContent='';t=setTimeout(()=>{stateR='go';start=performance.now();rx.classList.add('ready');rx.textContent='NHẤN NGAY!'},1200+rand()*2600)}else if(stateR==='wait'){clearTimeout(t);stateR='idle';rx.textContent='Quá sớm! Nhấn để thử lại.';$('#msg').textContent='Đừng đoán trước 😆'}else if(stateR==='go'){const ms=Math.round(performance.now()-start);best=Math.min(best,ms);stateR='done';rx.classList.remove('ready');rx.textContent=`${ms} ms`;$('#msg').textContent=`Tốt nhất: ${best} ms`;award('reaction',Math.max(20,500-ms),`${ms} ms`)}};cleanup=()=>clearTimeout(t);});

  register('aim', stage=>{let hits=0,start=0;stage.innerHTML=`<div class="message">Bấm 20 mục tiêu • <b id="stat">0/20</b></div><div id="area" class="aim-area"><button id="target" class="target">•</button></div>`;const area=$('#area'),tar=$('#target');function move(){const w=area.clientWidth-60,h=area.clientHeight-60;tar.style.left=Math.max(0,rand()*w)+'px';tar.style.top=Math.max(0,rand()*h)+'px'}tar.onclick=e=>{e.stopPropagation();if(!hits)start=performance.now();hits++;beep(740,.03);$('#stat').textContent=`${hits}/20`;if(hits>=20){const sec=(performance.now()-start)/1000;tar.remove();$('#stat').textContent=`${sec.toFixed(2)} giây`;award('aim',Math.max(30,500-Math.round(sec*20)),`20 hit / ${sec.toFixed(2)}s`)}else move()};setTimeout(move,50);});

  register('snake', stage=>{stage.innerHTML=`<div class="message">Điểm: <b id="score">0</b> • WASD / mũi tên</div><div class="canvas-wrap"><canvas id="cv" width="500" height="500"></canvas></div>`;const cv=$('#cv'),ctx=cv.getContext('2d'),N=20,S=cv.width/N;let snake=[{x:10,y:10},{x:9,y:10},{x:8,y:10}],dir={x:1,y:0},next=dir,food={x:15,y:10},score=0,dead=false;function newFood(){do{food={x:Math.floor(rand()*N),y:Math.floor(rand()*N)}}while(snake.some(s=>s.x===food.x&&s.y===food.y))}function draw(){ctx.clearRect(0,0,cv.width,cv.height);ctx.fillStyle='#1a2230';ctx.fillRect(0,0,cv.width,cv.height);ctx.fillStyle='#ef4444';ctx.fillRect(food.x*S+3,food.y*S+3,S-6,S-6);ctx.fillStyle='#22c55e';snake.forEach((p,i)=>ctx.fillRect(p.x*S+2,p.y*S+2,S-4,S-4));if(dead){ctx.fillStyle='white';ctx.font='bold 38px system-ui';ctx.textAlign='center';ctx.fillText('GAME OVER',250,250)}}function tick(){if(dead)return;dir=next;const h={x:snake[0].x+dir.x,y:snake[0].y+dir.y};if(h.x<0||h.y<0||h.x>=N||h.y>=N||snake.some(s=>s.x===h.x&&s.y===h.y)){dead=true;clearInterval(timer);award('snake',score*20,`Snake ${score}`);draw();return}snake.unshift(h);if(h.x===food.x&&h.y===food.y){score++;$('#score').textContent=score;newFood();beep(640)}else snake.pop();draw()}function key(e){const m={ArrowUp:{x:0,y:-1},w:{x:0,y:-1},W:{x:0,y:-1},ArrowDown:{x:0,y:1},s:{x:0,y:1},S:{x:0,y:1},ArrowLeft:{x:-1,y:0},a:{x:-1,y:0},A:{x:-1,y:0},ArrowRight:{x:1,y:0},d:{x:1,y:0},D:{x:1,y:0}};const n=m[e.key];if(n&&!(n.x===-dir.x&&n.y===-dir.y)){e.preventDefault();next=n}}window.addEventListener('keydown',key);let timer;function loop(){if(dead)return;tick();timer=setTimeout(loop,Math.max(34,110/speedFactor()))}timer=setTimeout(loop,110);cleanup=()=>{clearTimeout(timer);window.removeEventListener('keydown',key)};draw();});

  register('pong', stage=>{stage.innerHTML=`<div class="message"><b id="sc">0 - 0</b> • kéo chuột/chạm để di chuyển</div><canvas id="cv" width="640" height="420"></canvas>`;const cv=$('#cv'),ctx=cv.getContext('2d');let py=170,ay=170,bx=320,by=210,vx=4.5,vy=3.1,ps=0,as=0,over=false;function reset(d=1){bx=320;by=210;vx=4.5*d;vy=(rand()*4-2)||2}function move(y){const r=cv.getBoundingClientRect();py=(y-r.top)*cv.height/r.height-45;py=Math.max(0,Math.min(cv.height-90,py))}cv.onmousemove=e=>move(e.clientY);cv.ontouchmove=e=>{e.preventDefault();move(e.touches[0].clientY)};function tick(){if(over)return;ay+=(by-(ay+45))*.07*aiFactor();ay=Math.max(0,Math.min(cv.height-90,ay));const sf=Math.min(2.2,speedFactor());bx+=vx*sf;by+=vy*sf;if(by<8||by>cv.height-8)vy*=-1;if(vx<0&&bx<28&&bx>16&&by>py&&by<py+90){vx=Math.abs(vx)*1.035;beep(520,.02)}if(vx>0&&bx>cv.width-28&&bx<cv.width-16&&by>ay&&by<ay+90){vx=-Math.abs(vx)*1.035;beep(420,.02)}if(bx<0){as++;reset(1)}if(bx>cv.width){ps++;reset(-1)}$('#sc').textContent=`${ps} - ${as}`;if(ps>=7||as>=7){over=true;award('pong',ps>=7?200:40,ps>=7?'Thắng Pong':'Thua Pong')}draw()}function draw(){ctx.fillStyle='#0c1119';ctx.fillRect(0,0,cv.width,cv.height);ctx.strokeStyle='#2c3548';ctx.setLineDash([8,10]);ctx.beginPath();ctx.moveTo(320,0);ctx.lineTo(320,420);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='white';ctx.fillRect(14,py,12,90);ctx.fillRect(614,ay,12,90);ctx.beginPath();ctx.arc(bx,by,8,0,Math.PI*2);ctx.fill()}const timer=setInterval(tick,16);cleanup=()=>clearInterval(timer);draw();});

  register('breakout', stage=>{stage.innerHTML=`<div class="message">Gạch còn: <b id="bricks">40</b></div><canvas id="cv" width="640" height="460"></canvas>`;const cv=$('#cv'),ctx=cv.getContext('2d');let px=270,bx=320,by=370,vx=3.6,vy=-4.2,over=false;let bricks=[];for(let r=0;r<5;r++)for(let c=0;c<8;c++)bricks.push({x:34+c*72,y:35+r*34,w:62,h:22,live:true});function move(x){const r=cv.getBoundingClientRect();px=(x-r.left)*cv.width/r.width-50;px=Math.max(0,Math.min(540,px))}cv.onmousemove=e=>move(e.clientX);cv.ontouchmove=e=>{e.preventDefault();move(e.touches[0].clientX)};function tick(){if(over)return;const sf=Math.min(2.25,speedFactor());bx+=vx*sf;by+=vy*sf;if(bx<8||bx>632)vx*=-1;if(by<8)vy=Math.abs(vy);if(by>430&&by<447&&bx>px&&bx<px+100)vy=-Math.abs(vy);for(const b of bricks)if(b.live&&bx>b.x&&bx<b.x+b.w&&by>b.y&&by<b.y+b.h){b.live=false;vy*=-1;beep(700,.02);break}const left=bricks.filter(b=>b.live).length;$('#bricks').textContent=left;if(!left){over=true;award('breakout',400,'Phá sạch gạch')}if(by>470){over=true;award('breakout',(40-left)*6,'Breakout kết thúc')}draw()}function draw(){ctx.fillStyle='#0b1018';ctx.fillRect(0,0,640,460);ctx.fillStyle='#8b7aff';bricks.filter(b=>b.live).forEach(b=>ctx.fillRect(b.x,b.y,b.w,b.h));ctx.fillStyle='white';ctx.fillRect(px,435,100,10);ctx.beginPath();ctx.arc(bx,by,8,0,Math.PI*2);ctx.fill()}const timer=setInterval(tick,16);cleanup=()=>clearInterval(timer);draw();});

  const words=[['MAYTINH','Thiết bị dân văn phòng nhìn cả ngày'],['CAPHE','Thứ giúp nhiều người sống sót qua buổi sáng'],['HOP','Hoạt động đôi khi đáng lẽ là một email'],['DEADLINE','Ngày giờ khiến mọi người tăng tốc'],['BANPHIM','Có rất nhiều phím nhưng không mở được cửa'],['EXCEL','Nơi có ô nhưng không phải căn hộ'],['SLACK','Tên một công cụ nhắn tin phổ biến']];
  register('wordguess', stage=>{let idx=Math.floor(rand()*words.length),tries=0;const [ans,hint]=words[idx];stage.innerHTML=`<div class="stack center"><div class="eyebrow">Gợi ý</div><h2>${hint}</h2><input id="guess" class="field" placeholder="Nhập đáp án không dấu"><button id="go" class="primary-btn">Đoán</button><div id="msg" class="message"></div></div>`;$('#go').onclick=()=>{tries++;const v=$('#guess').value.toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s/g,'');if(v===ans){$('#msg').textContent=`✅ Đúng sau ${tries} lần!`;award('wordguess',Math.max(50,180-tries*15),'Đoán đúng từ')}else $('#msg').textContent='Chưa đúng, thử lại.'};});

  register('hangman', stage=>{const answer=words[Math.floor(rand()*words.length)][0], guessed=new Set();let wrong=0;stage.innerHTML=`<div class="word-box" id="word"></div><div class="message" id="msg"></div><div class="row" id="letters"></div>`;function draw(){const shown=[...answer].map(c=>guessed.has(c)?c:'_').join(' ');$('#word').textContent=shown;$('#msg').textContent=`Sai: ${wrong}/6`;const alpha='ABCDEFGHIJKLMNOPQRSTUVWXYZ';$('#letters').innerHTML=[...alpha].map(c=>`<button class="chip" data-c="${c}" ${guessed.has(c)?'disabled':''}>${c}</button>`).join('');$$('[data-c]',$('#letters')).forEach(x=>x.onclick=()=>{const c=x.dataset.c;if(guessed.has(c))return;guessed.add(c);if(!answer.includes(c))wrong++;if([...answer].every(ch=>guessed.has(ch))){$('#msg').textContent='🎉 Chính xác!';award('hangman',Math.max(50,180-wrong*20),'Thắng Hangman')}else if(wrong>=6){$('#msg').textContent=`Thua! Đáp án: ${answer}`;$$('[data-c]',$('#letters')).forEach(b=>b.disabled=true)}draw()})}draw();});

