  register('emoji', stage=>{const qs=[['☕💻','Cà phê và máy tính'],['📅⏰😱','Deadline'],['👥🗣️📊','Cuộc họp'],['🏠💻','Làm việc tại nhà'],['📧➡️🗑️','Xóa email'],['🍜🕛','Giờ ăn trưa']];let i=0,score=0;stage.innerHTML=`<div class="stack center"><div id="emo" style="font-size:72px"></div><div id="choices" class="choice-grid"></div><div id="msg" class="message"></div></div>`;function draw(){if(i>=qs.length){$('#emo').textContent='🏆';$('#choices').innerHTML='';$('#msg').textContent=`${score}/${qs.length} câu đúng`;award('emoji',score*40,'Hoàn thành Emoji Quiz');return}const correct=qs[i][1],opts=[correct,...qs.filter((_,j)=>j!==i).map(x=>x[1]).sort(()=>rand()-.5).slice(0,3)].sort(()=>rand()-.5);$('#emo').textContent=qs[i][0];$('#choices').innerHTML=opts.map(o=>`<button class="choice">${o}</button>`).join('');$$('.choice',$('#choices')).forEach(x=>x.onclick=()=>{if(x.textContent===correct)score++;i++;draw()})}draw();});

