  register('typing', stage=>{const texts=['Một ngày làm việc hiệu quả bắt đầu từ việc xác định rõ điều quan trọng nhất cần hoàn thành.','Đừng để một cuộc họp dài biến thành lý do khiến công việc thực sự không thể bắt đầu đúng giờ.','Cà phê có thể giúp bạn tỉnh táo nhưng một danh sách ưu tiên tốt mới giúp bạn hoàn thành công việc.'];const text=texts[Math.floor(rand()*texts.length)];let start=0,done=false;stage.innerHTML=`<div class="stack"><div class="typing-text">${text}</div><textarea id="type" class="typing-input" placeholder="Bắt đầu gõ ở đây..."></textarea><div id="msg" class="message"></div></div>`;const input=$('#type');input.oninput=()=>{if(!start)start=performance.now();if(done)return;if(input.value===text){done=true;const min=(performance.now()-start)/60000,w=text.trim().split(/\s+/).length,wpm=Math.round(w/min);$('#msg').textContent=`${wpm} WPM • chính xác 100%`;award('typing',wpm*4,`${wpm} WPM`)}};});

  register('rps', stage=>{let me=0,ai=0,round=0,done=false;const opts=[['✊','Búa'],['✋','Bao'],['✌️','Kéo']];stage.innerHTML=`<div class="message">Bạn <b id="sc">0 - 0</b> Máy</div><div class="row" id="opts"></div><div id="msg" class="message"></div>`;$('#opts').innerHTML=opts.map((o,i)=>`<button class="rps" data-i="${i}" title="${o[1]}">${o[0]}</button>`).join('');$$('.rps',$('#opts')).forEach(x=>x.onclick=()=>{if(done)return;const p=+x.dataset.i,c=Math.floor(rand()*3);round++;const win=(p-c+3)%3;if(win===1)me++;else if(win===2)ai++;$('#sc').textContent=`${me} - ${ai}`;$('#msg').textContent=`Bạn ${opts[p][0]} • Máy ${opts[c][0]} ${win===0?'→ Hòa':win===1?'→ Bạn thắng':'→ Máy thắng'}`;if(me===3||ai===3||round>=5){done=true;award('rps',me*60+(me>ai?80:0),me>ai?'Thắng BO5':'Kết thúc BO5')}});});

