  register('higher', stage=>{let cur=Math.floor(rand()*13)+1,score=0,over=false;const label=n=>n===1?'A':n===11?'J':n===12?'Q':n===13?'K':n;stage.innerHTML=`<div class="center"><div class="eyebrow">Lá hiện tại</div><div id="card" style="font-size:110px;font-weight:900">${label(cur)}</div><div class="row"><button class="primary-btn" data-h="1">Cao hơn ↑</button><button class="secondary-btn" data-h="0">Thấp hơn ↓</button></div><div id="msg" class="message">Chuỗi đúng: 0</div></div>`;$$('[data-h]').forEach(x=>x.onclick=()=>{if(over)return;const next=Math.floor(rand()*13)+1,high=x.dataset.h==='1',ok=next===cur?true:high?next>cur:next<cur;if(ok){score++;$('#msg').textContent=`Đúng! ${label(cur)} → ${label(next)} • chuỗi ${score}`}else{over=true;$('#msg').textContent=`Sai! ${label(cur)} → ${label(next)} • kết thúc ${score}`;award('higher',score*40,`Chuỗi ${score}`)}cur=next;$('#card').textContent=label(cur)});});

