  register('poll', stage=>{const polls=[['Cà phê','Trà'],['Remote','Office'],['Sáng sớm','Cú đêm'],['Excel','Google Sheets'],['Biển','Núi']];let i=0,a=0,b=0;stage.innerHTML=`<div class="party-card"><h2 id="q"></h2><div class="row"><button id="a" class="primary-btn"></button><button id="b" class="secondary-btn"></button></div><div id="msg" class="message"></div><button id="next" class="ghost-btn" title="Câu tiếp">→</button></div>`;function draw(){const p=polls[i%polls.length];$('#q').textContent='Chọn một bên';$('#a').textContent=`${p[0]} (${a})`;$('#b').textContent=`${p[1]} (${b})`;$('#msg').textContent=`Tổng ${a+b} vote`}$('#a').onclick=()=>{a++;draw()};$('#b').onclick=()=>{b++;draw()};$('#next').onclick=()=>{i++;a=b=0;draw();award('poll',5,'Poll mới')};draw();});

